import re


def slugify(text):
    text = text.strip().lower()
    # Replace punctuation marks with hyphen, preserve whitespace and alphanumeric characters
    result = ""
    for char in text:
        if not (char.isalnum() or char.isspace()):
            result += "-"
        else:
            result += char
    return result


def truncate(text, n):
    if len(text) <= n:
        return text
    return text[: n - 3] + "..."
EOF
